window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a6f3d84da8f67e11"]={"versions": [{"id": "FIG-a6f3d84da8f67e11", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zustandsdiagramm (State Machine) zur Spezifikation der auf Task-Ebene abgeleiteten Laufzeitzustände einer <code>RunnableEntity</code> im Kontext des AUTOSAR-Laufzeitumgebungs- (RTE) und Betriebssystem-Managements (OS-Task-Level).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Drei elementare Zustände:</p>\n<ul class=\"fig-list\"><li><code>Enabled</code>: Zustand der Ausführungsbereitschaft (Task aktiviert bzw. Runnable startbereit).\n</li><li><code>Running</code>: Zustand der aktiven CPU-Ausführung des Runnable-Codes.\n</li><li><code>Suspended</code>: Ruhezustand nach Beendigung der Ausführung.\n</li></ul>\n<p class=\"fig-p\">Zustandsübergänge (Transitionen):</p>\n<ul class=\"fig-list\"><li><code>runnable started</code>: Übergang von <code>Enabled</code> nach <code>Running</code>.\n</li><li><code>runnable returns</code>: Übergang von <code>Running</code> nach <code>Suspended</code>.\n</li><li>Transition ohne explizite Beschriftung von <code>Suspended</code> nach <code>Enabled</code> (Aktivierung/Triggerung des ausführenden OS-Tasks bzw. Runnables).\n</li><li><code>preempted</code>: Übergang von <code>Running</code> zurück nach <code>Enabled</code> bei Verdrängung.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Ein im Ruhezustand (<code>Suspended</code>) befindliches Runnable wird durch Aktivierung des zugeordneten Tasks in den Zustand <code>Enabled</code> versetzt.\n</li><li>Sobald der Scheduler den Task zuteilt, wechselt der Zustand über <code>runnable started</code> von <code>Enabled</code> zu <code>Running</code>.\n</li><li>Wird die Ausführung durch einen höher priorisierten Task unterbrochen, kehrt das Runnable über <code>preempted</code> in den Zustand <code>Enabled</code> zurück.\n</li><li>Nach regulärem Abschluss der Abarbeitung führt der Rücksprung über <code>runnable returns</code> vom Zustand <code>Running</code> in den Zustand <code>Suspended</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Modell beschreibt das deterministische Zustandsverhalten einer <code>RunnableEntity</code> bei Zuordnung zu OS-Tasks ohne interne Wartezustände (z. B. nicht-blockierende Ausführung / Basic Tasks). Für Implementierer von Software-Komponenten und RTE-Generatoren ist maßgeblich, dass ein Runnable nach Rückkehr (<code>runnable returns</code>) vollständig terminiert ist und ein erneuter Start (<code>runnable started</code>) stets die Re-Aktivierung über den Zustand <code>Enabled</code> voraussetzt. Verdrängung (<code>preempted</code>) erfordert die Einhaltung von Reentranz- und Datenkonsistenzanforderungen für unterbrechbare Tasks.</p>"}, {"id": "FIG-65879b453e52789d", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zustandsdiagramm (State Machine) zur Spezifikation der auf Task-Ebene abgeleiteten Laufzeitzustände einer <code>RunnableEntity</code> im Kontext des AUTOSAR-Laufzeitumgebungs- (RTE) und Betriebssystem-Managements (OS-Task-Level).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Drei elementare Zustände:</p>\n<ul class=\"fig-list\"><li><code>Enabled</code>: Zustand der Ausführungsbereitschaft (Task aktiviert bzw. Runnable startbereit).\n</li><li><code>Running</code>: Zustand der aktiven CPU-Ausführung des Runnable-Codes.\n</li><li><code>Suspended</code>: Ruhezustand nach Beendigung der Ausführung.\n</li></ul>\n<p class=\"fig-p\">Zustandsübergänge (Transitionen):</p>\n<ul class=\"fig-list\"><li><code>runnable started</code>: Übergang von <code>Enabled</code> nach <code>Running</code>.\n</li><li><code>runnable returns</code>: Übergang von <code>Running</code> nach <code>Suspended</code>.\n</li><li>Transition ohne explizite Beschriftung von <code>Suspended</code> nach <code>Enabled</code> (Aktivierung/Triggerung des ausführenden OS-Tasks bzw. Runnables).\n</li><li><code>preempted</code>: Übergang von <code>Running</code> zurück nach <code>Enabled</code> bei Verdrängung.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Ein im Ruhezustand (<code>Suspended</code>) befindliches Runnable wird durch Aktivierung des zugeordneten Tasks in den Zustand <code>Enabled</code> versetzt.\n</li><li>Sobald der Scheduler den Task zuteilt, wechselt der Zustand über <code>runnable started</code> von <code>Enabled</code> zu <code>Running</code>.\n</li><li>Wird die Ausführung durch einen höher priorisierten Task unterbrochen, kehrt das Runnable über <code>preempted</code> in den Zustand <code>Enabled</code> zurück.\n</li><li>Nach regulärem Abschluss der Abarbeitung führt der Rücksprung über <code>runnable returns</code> vom Zustand <code>Running</code> in den Zustand <code>Suspended</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Modell beschreibt das deterministische Zustandsverhalten einer <code>RunnableEntity</code> bei Zuordnung zu OS-Tasks ohne interne Wartezustände (z. B. nicht-blockierende Ausführung / Basic Tasks). Für Implementierer von Software-Komponenten und RTE-Generatoren ist maßgeblich, dass ein Runnable nach Rückkehr (<code>runnable returns</code>) vollständig terminiert ist und ein erneuter Start (<code>runnable started</code>) stets die Re-Aktivierung über den Zustand <code>Enabled</code> voraussetzt. Verdrängung (<code>preempted</code>) erfordert die Einhaltung von Reentranz- und Datenkonsistenzanforderungen für unterbrechbare Tasks.</p>"}], "trans": [{"from": "FIG-a6f3d84da8f67e11", "to": "FIG-65879b453e52789d", "fr": "R3.0.7", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
